mapper.select:
select 
from business_status_transitions bst
where bst.business_type = #{businessType}
  and bst.definition_version = #{definitionVersion}
  and bst.from_status_code = #{fromStatusCode}
  and bst.to_status_code = #{toStatusCode}
  and bst.executor_role_code = #{executorRoleCode}

select count(*)
from business_status_codes
where business_type = #{businessType}
  and definition_version = #{definitionVersion}
  and status_code = #{statusCode}

select count(*)
from roles
where role_code = #{roleCode}
